/* @autogenerated */
import { ComponentFixture, TestBed } from '@angular/core/testing';
import { MAT_DIALOG_DATA, MatDialogRef } from '@angular/material/dialog';
import { TranslocoTestingModule } from '@jsverse/transloco';
import { of } from 'rxjs';
import { EditConflictDialogComponent, EditConflictDialogData } from './edit-conflict-dialog.component';
import { ConflictField } from './edit-conflict.model';

interface Role {
  uid: string;
  name: string;
  description: string;
  resourceServer: { $ref: string } | null;
  version: number;
}

const ORIGINAL: Role = { uid: 'r1', name: 'Admin', description: 'd', resourceServer: { $ref: 'rs1' }, version: 1 };
const SENT: Role = { ...ORIGINAL, name: 'Administrators' };
const CURRENT: Role = { ...ORIGINAL, name: 'Admins', resourceServer: { $ref: 'rs2' }, version: 2 };

const SERVERS: Record<string, string> = { rs1: 'Phylax API', rs2: 'Billing API' };

const FIELDS: ConflictField[] = [
  { name: 'name', label: 'access.role.form-group.name' },
  { name: 'description', label: 'access.role.form-group.description' },
  {
    name: 'resourceServer',
    label: 'access.role.form-group.resource-server',
    display: (value: { $ref: string }) => of(SERVERS[value.$ref]),
  },
];

describe('EditConflictDialogComponent', () => {
  let fixture: ComponentFixture<EditConflictDialogComponent<Role>>;
  let component: EditConflictDialogComponent<Role>;
  let dialogRef: jasmine.SpyObj<MatDialogRef<unknown>>;

  const el = (): HTMLElement => fixture.nativeElement;
  const rowOf = (field: string) => el().querySelector<HTMLElement>(`[data-field="${field}"]`);
  const radio = (field: string, choice: 'sent' | 'current') =>
    rowOf(field)!.querySelector<HTMLInputElement>(`mat-radio-button[value="${choice}"] input`)!;
  const button = (text: string) =>
    Array.from(el().querySelectorAll<HTMLButtonElement>('button')).find((b) => b.textContent!.includes(text))!;

  beforeEach(() => {
    dialogRef = jasmine.createSpyObj('MatDialogRef', ['close']);
    const data: EditConflictDialogData<Role> = {
      conflict: { original: ORIGINAL, sent: SENT, current: CURRENT },
      fields: FIELDS,
    };
    TestBed.configureTestingModule({
      imports: [
        EditConflictDialogComponent,
        TranslocoTestingModule.forRoot({
          langs: {
            en: {
              editConflict: { apply: 'Apply', cancel: 'Cancel', keepMine: 'Keep mine', useServer: 'Use server' },
            },
          },
          translocoConfig: { availableLangs: ['en'], defaultLang: 'en' },
        }),
      ],
      providers: [
        { provide: MAT_DIALOG_DATA, useValue: data },
        { provide: MatDialogRef, useValue: dialogRef },
      ],
    });
    fixture = TestBed.createComponent(EditConflictDialogComponent<Role>);
    component = fixture.componentInstance;
    fixture.detectChanges();
  });

  it('shows the conflict unselected and the server-only change already chosen', () => {
    expect(rowOf('name')!.classList).toContain('state-conflict');
    expect(radio('name', 'sent').checked).toBeFalse();
    expect(radio('name', 'current').checked).toBeFalse();
    expect(radio('resourceServer', 'current').checked).toBeTrue();
  });

  it('hides unchanged fields until the toggle is switched on', () => {
    expect(rowOf('description')).toBeNull();
    component.showUnchanged.set(true);
    fixture.detectChanges();
    expect(rowOf('description')).not.toBeNull();
  });

  it('shows references by their label, not as $ref', () => {
    const text = rowOf('resourceServer')!.textContent!;
    expect(text).toContain('Phylax API');
    expect(text).toContain('Billing API');
    expect(text).not.toContain('rs1');
  });

  it('labels each radio group with the field name', () => {
    const group = rowOf('name')!.querySelector('mat-radio-group')!;
    const label = el().querySelector('#' + group.getAttribute('aria-labelledby'));
    expect(label).not.toBeNull();
  });

  it('enables Apply only once the conflict is resolved', () => {
    expect(button('Apply').disabled).toBeTrue();
    radio('name', 'sent').click();
    fixture.detectChanges();
    expect(button('Apply').disabled).toBeFalse();
  });

  it('applies the merged value with the current version', () => {
    radio('name', 'sent').click();
    fixture.detectChanges();
    button('Apply').click();
    expect(dialogRef.close).toHaveBeenCalledWith({
      uid: 'r1',
      name: 'Administrators',
      description: 'd',
      resourceServer: { $ref: 'rs2' },
      version: 2,
    });
  });

  it('closes with null on cancel', () => {
    button('Cancel').click();
    expect(dialogRef.close).toHaveBeenCalledWith(null);
  });

  it('keeps my changes in conflicts and the server-only changes', () => {
    button('Keep mine').click();
    fixture.detectChanges();
    button('Apply').click();
    expect(dialogRef.close).toHaveBeenCalledWith(
      jasmine.objectContaining({ name: 'Administrators', resourceServer: { $ref: 'rs2' }, version: 2 }),
    );
  });

  it('uses everything from the server', () => {
    button('Use server').click();
    fixture.detectChanges();
    button('Apply').click();
    expect(dialogRef.close).toHaveBeenCalledWith(CURRENT);
  });
});
